import sys

data = sys.stdin.read().split()
N, D = int(data[0]), int(data[1])

def is_prime(x):
    if x < 2:
        return False
    if x % 2 == 0:
        return x == 2
    d = 3
    while d * d <= x:
        if x % d == 0:
            return False
        d += 2
    return True

res = []
for x in range(10 ** (N - 1), 10 ** N):
    if x >= 2 and is_prime(x):
        s = str(x)
        counts = {}
        for ch in s:
            counts[ch] = counts.get(ch, 0) + 1
        if counts.get(str(D), 0) == max(counts.values()):
            res.append(x)
print(' '.join(map(str, res)) if res else -1)

